:root {
    --bg-primary: #FFFFFF;
    --bg-secondary: #F5F5F5;
    --text-primary: #141414;
    --text-secondary: #555555;
    --accent: #2563EB; /* Electric Blue */
    --accent-hover: #1D4ED8;
    --border: #E5E5E5;
    --font-sans: 'Inter', sans-serif;
    --radius-sm: 8px;
    --radius-md: 12px;
    --radius-lg: 20px;
    --radius-full: 9999px;
    --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
    --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-sans);
    color: var(--text-primary);
    background-color: var(--bg-primary);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
}

a {
    color: inherit;
    text-decoration: none;
}

ul {
    list-style: none;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 24px;
}

.text-center {
    text-align: center;
}

/* Typography */
h1, h2, h3, h4 {
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: -0.02em;
}

h1 { font-size: 3.5rem; }
h2 { font-size: 2.5rem; margin-bottom: 1rem; }
h3 { font-size: 1.5rem; margin-bottom: 0.5rem; }
p { color: var(--text-secondary); }

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 10px 20px;
    border-radius: var(--radius-full);
    font-weight: 500;
    font-size: 0.95rem;
    transition: all 0.2s ease;
    cursor: pointer;
    border: 1px solid transparent;
}

.btn-lg {
    padding: 14px 28px;
    font-size: 1.1rem;
}

.btn-primary {
    background-color: var(--text-primary);
    color: var(--bg-primary);
}

.btn-primary:hover {
    background-color: #000;
    transform: translateY(-1px);
    box-shadow: var(--shadow-md);
}

.btn-secondary {
    background-color: var(--bg-primary);
    color: var(--text-primary);
    border-color: var(--border);
}

.btn-secondary:hover {
    background-color: var(--bg-secondary);
}

.link-btn {
    font-weight: 500;
    color: var(--text-primary);
    transition: color 0.2s;
}

.link-btn:hover {
    color: var(--text-secondary);
}

/* Announcement Bar */
.announcement-bar {
    background-color: var(--bg-secondary);
    padding: 12px 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    font-size: 0.9rem;
    font-weight: 500;
    border-bottom: 1px solid var(--border);
}

.announcement-bar .pill {
    background-color: var(--accent);
    color: white;
    padding: 2px 8px;
    border-radius: var(--radius-full);
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
}

.announcement-bar i {
    color: var(--text-secondary);
}

/* Header */
.header {
    padding: 20px 0;
    position: sticky;
    top: 0;
    background-color: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(8px);
    z-index: 100;
    border-bottom: 1px solid transparent;
    transition: border-color 0.3s;
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    display: flex;
    align-items: center;
    gap: 8px;
    font-weight: 700;
    font-size: 1.25rem;
    letter-spacing: -0.02em;
}

.logo i {
    font-size: 1.5rem;
    color: var(--accent);
}

.nav-links {
    display: flex;
    gap: 32px;
}

.nav-links a {
    font-weight: 500;
    color: var(--text-secondary);
    transition: color 0.2s;
}

.nav-links a:hover {
    color: var(--text-primary);
}

.nav-actions {
    display: flex;
    align-items: center;
    gap: 24px;
}

/* Hero Section */
.hero {
    padding: 80px 0 60px;
    text-align: center;
}

.hero-title {
    margin-bottom: 24px;
}

.hero-subtitle {
    font-size: 1.25rem;
    max-width: 600px;
    margin: 0 auto 40px;
}

.hero-actions {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    margin-bottom: 60px;
}

.hero-preview {
    position: relative;
    max-width: 1000px;
    margin: 0 auto;
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-lg);
    background-color: var(--bg-secondary);
}

.hero-image-placeholder {
    position: relative;
    width: 100%;
    padding-top: 56.25%; /* 16:9 Aspect Ratio */
}

.hero-image-placeholder img {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Trusted By */
.trusted-by {
    padding: 40px 0;
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    background-color: #FAFAFA;
    overflow: hidden;
}

.trusted-label {
    text-align: center;
    font-size: 0.9rem;
    font-weight: 500;
    margin-bottom: 24px;
}

.logo-row {
    position: relative;
    width: 100vw;
    margin-left: calc(-50vw + 50%);
    display: flex;
    overflow: hidden;
}

.logo-marquee {
    display: flex;
    align-items: center;
    gap: 60px;
    animation: marquee-horizontal 30s linear infinite;
    padding: 0 30px;
}

.logo-marquee span {
    font-size: 1.25rem;
    font-weight: 700;
    color: #999;
    letter-spacing: -0.03em;
    white-space: nowrap;
}

@keyframes marquee-horizontal {
    0% { transform: translateX(0); }
    100% { transform: translateX(calc(-50% - 30px)); }
}

/* Stats Section */
.stats {
    padding: 100px 0;
    background-color: var(--text-primary);
    color: white;
}

.stats-header h2 {
    color: white;
    text-align: center;
    margin-bottom: 60px;
}

.stats-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 40px;
    text-align: center;
}

.stat-card {
    padding: 20px;
}

.stat-number {
    font-size: 4rem;
    font-weight: 700;
    letter-spacing: -0.04em;
    margin-bottom: 8px;
    background: linear-gradient(135deg, #fff 0%, #aaa 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.stat-label {
    font-size: 1.1rem;
    font-weight: 500;
    color: #999;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* Features: Search */
.features-search {
    padding: 100px 0;
    background-color: var(--bg-secondary);
}

.section-header {
    margin-bottom: 40px;
}

.search-tabs {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-bottom: 32px;
    flex-wrap: wrap;
}

.tab-btn {
    padding: 12px 24px;
    background: transparent;
    border: none;
    font-size: 1rem;
    font-weight: 500;
    color: var(--text-secondary);
    cursor: pointer;
    border-radius: var(--radius-full);
    transition: all 0.2s ease;
}

.tab-btn:hover {
    color: var(--text-primary);
    background-color: rgba(0,0,0,0.05);
}

.tab-btn.active {
    background-color: var(--bg-primary);
    color: var(--text-primary);
    box-shadow: var(--shadow-sm);
}

.search-filters-wrapper {
    overflow-x: auto;
    padding-bottom: 20px;
    margin-bottom: 40px;
    -ms-overflow-style: none;
    scrollbar-width: none;
}

.search-filters-wrapper::-webkit-scrollbar {
    display: none;
}

.search-filters {
    display: flex;
    gap: 12px;
    width: max-content;
    margin: 0 auto;
    padding: 0 20px;
}

.pill-btn {
    padding: 8px 16px;
    background-color: var(--bg-primary);
    border: 1px solid var(--border);
    border-radius: var(--radius-full);
    font-size: 0.9rem;
    color: var(--text-secondary);
    cursor: pointer;
    transition: all 0.2s;
    white-space: nowrap;
}

.pill-btn:hover {
    border-color: #ccc;
    color: var(--text-primary);
}

.pill-btn.active {
    background-color: var(--text-primary);
    color: white;
    border-color: var(--text-primary);
}

.results-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 24px;
}

.result-card {
    background: var(--bg-primary);
    border-radius: var(--radius-md);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    aspect-ratio: 3/4;
    position: relative;
    transition: transform 0.3s ease;
}

.result-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-md);
}

.img-ph {
    width: 100%;
    height: 100%;
    background-color: #eaeaea;
    background-image: linear-gradient(135deg, #f5f5f5 25%, transparent 25%, transparent 50%, #f5f5f5 50%, #f5f5f5 75%, transparent 75%, transparent);
    background-size: 20px 20px;
    opacity: 0.8;
}

/* Features: Flows */
.features-flows {
    padding: 120px 0;
}

.flows-container {
    display: flex;
    align-items: center;
    gap: 60px;
}

.flows-content {
    flex: 1;
}

.flows-content h2 {
    margin-bottom: 30px;
}

.flows-toggle {
    display: inline-flex;
    background-color: var(--bg-secondary);
    padding: 4px;
    border-radius: var(--radius-full);
    position: relative;
    margin-bottom: 24px;
}

.toggle-btn {
    position: relative;
    z-index: 1;
    padding: 10px 24px;
    border: none;
    background: transparent;
    font-size: 0.95rem;
    font-weight: 500;
    color: var(--text-secondary);
    cursor: pointer;
    border-radius: var(--radius-full);
    transition: color 0.3s ease;
}

.toggle-btn.active {
    color: var(--text-primary);
}

.flows-description p {
    font-size: 1.1rem;
    line-height: 1.6;
}

.hidden {
    display: none !important;
}

.flows-visual {
    flex: 1;
    display: flex;
    justify-content: center;
}

.mock-phone {
    width: 300px;
    height: 600px;
    background-color: var(--text-primary);
    border-radius: 40px;
    padding: 12px;
    position: relative;
    box-shadow: var(--shadow-lg);
}

.video-ui, .proto-ui {
    width: 100%;
    height: 100%;
    background-color: var(--bg-primary);
    border-radius: 30px;
    overflow: hidden;
    position: relative;
}

.play-icon {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 60px;
    height: 60px;
    background-color: rgba(0,0,0,0.5);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 24px;
    z-index: 10;
    backdrop-filter: blur(4px);
}

.hotspot {
    position: absolute;
    top: 60%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 30px;
    height: 30px;
    background-color: rgba(37, 99, 235, 0.3);
    border: 2px solid var(--accent);
    border-radius: 50%;
    z-index: 10;
}

.pulse {
    animation: pulse-animation 2s infinite;
}

@keyframes pulse-animation {
    0% { transform: translate(-50%, -50%) scale(0.9); opacity: 1; }
    50% { transform: translate(-50%, -50%) scale(1.5); opacity: 0; }
    100% { transform: translate(-50%, -50%) scale(0.9); opacity: 0; }
}

/* Features: Tools */
.features-tools {
    padding: 100px 0;
    background-color: #FAFAFA;
}

.tools-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
}

.tool-card {
    background: var(--bg-primary);
    padding: 40px 32px;
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-sm);
    text-align: center;
    transition: transform 0.3s;
}

.tool-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-md);
}

.tool-visual {
    width: 64px;
    height: 64px;
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 28px;
    margin: 0 auto 24px;
}

.tool-visual.figma { background: #E5F3FF; color: #0070F3; }
.tool-visual.collections { background: #F3E8FF; color: #9333EA; }
.tool-visual.comments { background: #DCFCE7; color: #16A34A; }

.tool-card h3 {
    margin-bottom: 12px;
}

.tool-card p {
    font-size: 0.95rem;
    line-height: 1.6;
}

/* Testimonials */
.testimonials {
    padding: 100px 0;
    overflow: hidden;
}

.testimonials-carousel {
    display: flex;
    flex-direction: column;
    gap: 24px;
    margin-top: 40px;
}

.marquee-row {
    position: relative;
    width: 100vw;
    margin-left: calc(-50vw + 50%);
    display: flex;
}

.marquee-content {
    display: flex;
    gap: 24px;
    padding: 0 12px;
}

.marquee-row.right .marquee-content {
    animation: marquee-right 40s linear infinite;
}

.marquee-row.left .marquee-content {
    animation: marquee-left 40s linear infinite;
}

@keyframes marquee-right {
    0% { transform: translateX(0); }
    100% { transform: translateX(calc(-50% - 12px)); }
}

@keyframes marquee-left {
    0% { transform: translateX(calc(-50% - 12px)); }
    100% { transform: translateX(0); }
}

.testimonial-card {
    background-color: var(--bg-secondary);
    padding: 32px;
    border-radius: var(--radius-md);
    width: 400px;
    flex-shrink: 0;
}

.testimonial-card p {
    font-size: 1.05rem;
    line-height: 1.6;
    color: var(--text-primary);
    margin-bottom: 24px;
    font-style: italic;
}

.testimonial-card .author {
    font-size: 0.95rem;
    color: var(--text-secondary);
}

.testimonial-card .author strong {
    color: var(--text-primary);
}

/* CTA Section */
.cta-section {
    padding: 120px 0 0;
    background-color: var(--text-primary);
    color: white;
    overflow: hidden;
}

.cta-content h2 {
    color: white;
    font-size: 3rem;
    margin-bottom: 20px;
}

.cta-content p {
    color: #aaa;
    font-size: 1.25rem;
    margin-bottom: 40px;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.cta-actions {
    display: flex;
    justify-content: center;
    gap: 16px;
    margin-bottom: 80px;
}

.cta-actions .btn-primary {
    background-color: var(--accent);
    color: white;
}

.cta-actions .btn-primary:hover {
    background-color: var(--accent-hover);
}

.cta-actions .btn-secondary {
    background-color: transparent;
    color: white;
    border-color: #555;
}

.cta-actions .btn-secondary:hover {
    background-color: rgba(255,255,255,0.1);
}

.app-icons-marquee {
    display: flex;
    flex-direction: column;
    gap: 16px;
    padding-bottom: 40px;
}

.icon-row {
    display: flex;
    width: 100vw;
    margin-left: calc(-50vw + 50%);
}

.icon-content {
    display: flex;
    gap: 16px;
    padding: 0 8px;
}

.icon-row.right .icon-content {
    animation: marquee-right 30s linear infinite;
}

.icon-row.left .icon-content {
    animation: marquee-left 30s linear infinite;
}

.app-icon {
    width: 80px;
    height: 80px;
    background-color: rgba(255,255,255,0.05);
    border-radius: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 36px;
    color: rgba(255,255,255,0.6);
    flex-shrink: 0;
    transition: color 0.3s, background-color 0.3s;
}

.app-icon:hover {
    color: white;
    background-color: rgba(255,255,255,0.1);
}

/* Footer */
.footer {
    background-color: var(--bg-secondary);
    padding: 80px 0 40px;
}

.footer-top {
    display: flex;
    justify-content: space-between;
    margin-bottom: 60px;
    flex-wrap: wrap;
    gap: 40px;
}

.footer-brand {
    max-width: 300px;
}

.footer-brand .logo {
    margin-bottom: 16px;
}

.footer-links {
    display: flex;
    gap: 80px;
    flex-wrap: wrap;
}

.link-group {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.link-group h4 {
    font-size: 1rem;
    margin-bottom: 8px;
}

.link-group a {
    color: var(--text-secondary);
    font-size: 0.95rem;
    transition: color 0.2s;
}

.link-group a:hover {
    color: var(--text-primary);
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 32px;
    border-top: 1px solid var(--border);
    font-size: 0.9rem;
    color: var(--text-secondary);
    flex-wrap: wrap;
    gap: 20px;
}

.legal-links {
    display: flex;
    gap: 24px;
}

.legal-links a:hover {
    color: var(--text-primary);
}

/* Responsive Design */
@media (max-width: 1024px) {
    h1 { font-size: 3rem; }
    h2 { font-size: 2.2rem; }
    .flows-container { flex-direction: column; }
    .flows-visual { width: 100%; }
}

@media (max-width: 768px) {
    h1 { font-size: 2.5rem; }
    .nav-links { display: none; }
    .stats-grid { grid-template-columns: 1fr; gap: 24px; }
    .tools-grid { grid-template-columns: 1fr; }
    .footer-top { flex-direction: column; }
    .footer-links { gap: 40px; }
}

@media (max-width: 480px) {
    h1 { font-size: 2rem; }
    h2 { font-size: 1.8rem; }
    .hero-actions { flex-direction: column; width: 100%; }
    .hero-actions .btn { width: 100%; }
    .cta-actions { flex-direction: column; width: 100%; }
    .cta-actions .btn { width: 100%; }
    .nav-actions { display: none; }
    .testimonial-card { width: 300px; padding: 24px; }
}

document.addEventListener('DOMContentLoaded', () => {

    // 1. Stats Counter Animation on Scroll
    const statsSection = document.getElementById('stats-section');
    const statNumbers = document.querySelectorAll('.stat-number');
    let hasAnimated = false;

    const animateValue = (obj, start, end, duration) => {
        let startTimestamp = null;
        const step = (timestamp) => {
            if (!startTimestamp) startTimestamp = timestamp;
            const progress = Math.min((timestamp - startTimestamp) / duration, 1);
            // Ease out cubic
            const easeOut = 1 - Math.pow(1 - progress, 3);
            const current = Math.floor(start + easeOut * (end - start));

            // Format with commas
            obj.innerHTML = current.toLocaleString();

            if (progress < 1) {
                window.requestAnimationFrame(step);
            } else {
                obj.innerHTML = end.toLocaleString();
            }
        };
        window.requestAnimationFrame(step);
    };

    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting && !hasAnimated) {
            hasAnimated = true;
            statNumbers.forEach((stat, index) => {
                const target = parseInt(stat.getAttribute('data-target'), 10);
                setTimeout(() => {
                    animateValue(stat, 0, target, 2000);
                }, index * 200); // Stagger start
            });
        }
    }, { threshold: 0.5 });

    if (statsSection) {
        observer.observe(statsSection);
    }

    // 2. Features: Search - Tabs & Filters
    const tabBtns = document.querySelectorAll('.tab-btn');
    const pillBtns = document.querySelectorAll('.pill-btn');
    const resultsGrid = document.getElementById('search-results-grid');

    // Generate random layout to simulate fetching data
    const generateMockResults = () => {
        resultsGrid.innerHTML = '';
        const count = Math.floor(Math.random() * 4) + 6; // 6 to 9 items
        for(let i = 0; i < count; i++) {
            const el = document.createElement('div');
            el.className = 'result-card';
            // Randomly switch background color to show it "changed"
            const hue = Math.floor(Math.random() * 360);
            const content = `<div class="img-ph" style="background-color: hsl(${hue}, 10%, 90%);"></div>`;
            el.innerHTML = content;
            resultsGrid.appendChild(el);
        }
    };

    tabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            tabBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            // Trigger visual refresh of results
            resultsGrid.style.opacity = '0.5';
            setTimeout(() => {
                generateMockResults();
                resultsGrid.style.opacity = '1';
            }, 200);
        });
    });

    pillBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            pillBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            // Trigger visual refresh of results
            resultsGrid.style.opacity = '0.5';
            setTimeout(() => {
                generateMockResults();
                resultsGrid.style.opacity = '1';
            }, 200);
        });
    });

    // 3. Features: Flows - Toggle View
    const toggleBtns = document.querySelectorAll('.flows-toggle .toggle-btn');
    const descVideo = document.getElementById('flows-desc-video');
    const descPrototype = document.getElementById('flows-desc-prototype');
    const viewVideo = document.getElementById('view-video');
    const viewPrototype = document.getElementById('view-prototype');

    toggleBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            const view = btn.getAttribute('data-view');

            toggleBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            if (view === 'video') {
                descVideo.classList.remove('hidden');
                descPrototype.classList.add('hidden');
                viewVideo.classList.remove('hidden');
                viewPrototype.classList.add('hidden');
            } else {
                descVideo.classList.add('hidden');
                descPrototype.classList.remove('hidden');
                viewVideo.classList.add('hidden');
                viewPrototype.classList.remove('hidden');
            }
        });
    });

});

