.flows-toggle {
    display: inline-flex;
    background-color: var(--border);
    padding: 4px;
    border-radius: var(--radius-full);
    position: relative;
    margin-bottom: 24px;
}

.toggle-btn {
    position: relative;
    z-index: 1;
    padding: 10px 24px;
    border: none;
    background: transparent;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--text-secondary);
    cursor: pointer;
    border-radius: var(--radius-full);
    transition: all 0.3s ease;
}

.toggle-btn:hover {
    color: var(--text-primary);
}

.toggle-btn.active {
    color: var(--text-primary);
    background-color: var(--bg-primary);
    box-shadow: var(--shadow-sm);
}

